import React,{useState} from 'react';
import {useResource} from '../../shared/state.js';
import {ResourceState} from '../../shared/ui.jsx';
export function WritingOverview({call,novelId,tick,run,busy,onChapter}){
 const [poll,setPoll]=useState(0),[target,setTarget]=useState(''),[count,setCount]=useState(100);
 const resource=useResource(()=>Promise.all([call('writing.stats.get',{novelId}),call('writing.foreshadow.list',{novelId})]),[call,novelId,tick,poll]);
 return <div className="structure-page"><h2>作品概览</h2><p className="muted">只统计已保存正文：含标点、不计空白，排除历史、设定和删除章。</p><ResourceState resource={resource}>{resource.value&&(()=>{const [s,foreshadows]=resource.value,max=Math.max(1,...s.rows.map(r=>r.words));return <><div className="stats-grid"><div><small>正文总字数</small><strong>{s.words.toLocaleString('zh-CN')}</strong></div><div><small>章节</small><strong>{s.chapters}</strong></div><div><small>目标进度</small><strong>{s.goal.target?Math.round(s.words/s.goal.target*100)+'%':'未设置'}</strong></div></div><div className="row"><label>目标字数<input aria-label="目标字数" type="number" min="1" placeholder={s.goal.target?.toString()||'可不填'} value={target} onChange={e=>setTarget(e.target.value)}/></label><button disabled={busy||!!target&&(!Number.isSafeInteger(Number(target))||Number(target)<1)} onClick={()=>run(async()=>{await call('writing.goal.set',{novelId,expectedRevision:s.goal.revision,target:target?Number(target):null,reason:'作者设置字数目标'});setPoll(n=>n+1);})}>{target?'保存目标':'清除目标'}</button></div><h3>分卷汇总</h3>{s.volumes.filter(v=>v.chapters).map(v=><p key={v.id||'none'}>{v.title} · {v.chapters} 章 · {v.words.toLocaleString('zh-CN')} 字</p>)}<h3>章节字数</h3>{s.rows.slice(0,count).map(r=><div key={r.id} className="chapter-stat"><button onClick={()=>onChapter(r.id)}>{r.title}</button><span>{r.words} 字</span><meter min="0" max={max} value={r.words} aria-label={`${r.title}字数`}/></div>)}{s.rows.length>count&&<button onClick={()=>setCount(n=>n+100)}>显示更多章节</button>}<h3>伏笔</h3><p>共 {foreshadows.length} 条，已回收 {foreshadows.filter(f=>f.status==='recovered').length} 条。</p>{foreshadows.filter(f=>f.due||f.review).map(f=><p className="notice" key={f.id}>{f.title}{f.due?` · 已到计划回收章「${f.targetTitle}」，尚未回收`:''}{f.review?' · 正文依据需复核':''}</p>)}</>;})()}</ResourceState></div>;
}
